self.addEventListener('install', function(event) {
  event.waitUntil(caches.open(CACHE).then(function(cache) {
    // One URL at a time, each failure swallowed: `addAll` is all-or-nothing,
    // and a single missing file would otherwise leave the site with no service
    // worker at all. Missing shell entries are caught by the PWA probe
    // (solution/cdp_pwa_check.js), not by breaking the install.
    return Promise.all(PRECACHE.map(function(url) {
      return cache.add(new Request(url, {cache: 'reload'})).catch(function() {});
    }));
  }).then(function() {
    return self.skipWaiting();
  }));
});

self.addEventListener('activate', function(event) {
  event.waitUntil(caches.keys().then(function(keys) {
    return Promise.all(keys.filter(function(key) {
      return key !== CACHE;
    }).map(function(key) {
      return caches.delete(key);
    }));
  }).then(function() {
    return self.clients.claim();
  }));
});

self.addEventListener('fetch', function(event) {
  var request = event.request;
  if (request.method !== 'GET') return;
  var url = new URL(request.url);
  // Cross-origin (the analytics beacon, a Companion on the LAN) is not ours
  // to cache.
  if (url.origin !== self.location.origin) return;
  // Range requests (media scrubbing) cannot be answered from a full body.
  if (request.headers.has('range')) return;

  event.respondWith(caches.match(request).then(function(hit) {
    if (hit) return hit;
    return fetch(request).then(function(response) {
      // Cache successful same-origin responses only: an opaque or error
      // response, stored, would be served forever.
      if (response && response.status === 200 && response.type === 'basic') {
        var copy = response.clone();
        caches.open(CACHE).then(function(cache) {
          cache.put(request, copy);
        });
      }
      return response;
    }).catch(function() {
      // Offline. A navigation to the app shell still opens (the start_url, or
      // the site root); any other page is genuinely unavailable.
      if (request.mode === 'navigate' &&
          (url.pathname.endsWith('/' + INDEX_FILE) || url.pathname.endsWith('/'))) {
        return caches.match('index.html');
      }
      return Response.error();
    });
  }));
});
